"""Private-copy fault proofs for ledger population, retries, sources and gate claims."""
import argparse
import os
import sys
from pathlib import Path
import shutil
import subprocess
import tempfile
ROOT=Path(__file__).resolve().parents[1]
CASES=[
 ('populated-evidence','scripts/measure_resources.ts',"INSERT INTO candidate_evidence SELECT id,id FROM tasks WHERE id>=? AND id<?","INSERT INTO candidate_evidence SELECT id,id FROM tasks WHERE id>=? AND id<? AND 0",'measure',''),
 ('safe-refusal','collectors/local/src/academic_os/jobs.py',"return 'retry' if error.code == 429","return 'failed' if error.code == 429",'retry','test_transient_refusal'),
 ('backoff','collectors/local/src/academic_os/jobs.py','BASE_DELAY = 30','BASE_DELAY = 0','retry','test_restart_mid_backoff'),
 ('exhaustion','collectors/local/src/academic_os/jobs.py',"count < MAX_ATTEMPTS[phase]","count < 100",'retry','test_permanent_failure'),
 ('unknown-not-replayed','collectors/local/src/academic_os/jobs.py',"    return 'unknown'\n\n\n@contextmanager","    return 'retry'\n\n\n@contextmanager",'retry','test_ambiguous_extraction'),
 ('crash-claim','collectors/local/src/academic_os/jobs.py',"self.finish(ident,'unknown','INTERRUPTED_ATTEMPT')","self.finish(ident,'retry','INTERRUPTED_ATTEMPT')",'retry','test_process_death'),
 ('retry-consent','collectors/local/src/academic_os/pipeline.py',"            policy=self.policy(source)\n","            policy=payload['policy']\n",'retry','test_revoked_or_changed'),
 ('sync-receipt','collectors/local/src/academic_os/sync.py',"receipt['data'].get('batch_id')!=value['batch_id']","False",'retry','test_sync_only'),
 ('source-isolation','collectors/local/src/academic_os/pipeline.py',"DELETE FROM processing_consent WHERE source_id=?","DELETE FROM processing_consent WHERE source_id=? OR 1=1",'operations','test_two_sources'),
 ('stale-form','collectors/local/src/academic_os/operations.py',"if row[0]!=expected:","if False:",'operations','test_stale_generation'),
 ('pause-not-wipe','collectors/local/src/academic_os/operations.py',"UPDATE source_operations SET local_paused=? WHERE source_id=? AND EXISTS(SELECT 1 FROM sources WHERE id=? AND generation=?)","UPDATE sources SET enabled=0 WHERE id=?2 AND id=?3 AND generation=?4 AND ?1>=0",'operations','test_pause_cannot'),
 ('missing-selection','collectors/local/src/academic_os/operations.py',"ident=value.get('source_id');expected=value.get('generation')","ident=pipeline.store.db.execute('SELECT id FROM sources ORDER BY id').fetchone()[0];expected=value.get('generation')",'operations','test_two_sources'),
 ('purge-needs-linux-ack','collectors/local/src/academic_os/operations.py','ack_generation!=generation or not ack_at or ','','operations','test_purge_stays'),
 ('terminal-job-pages','collectors/local/src/academic_os/pipeline.py',"(' WHERE rowid<?' if before is not None else '')","(' WHERE rowid<=?' if before is not None else '')",'operations','test_terminal_jobs'),
 ('stale-gate','docs/STATUS.md','Backup tombstone generations survive disposable SQLite restore (locally verified).','Backup tombstones remain unverified.','gate',''),
 ('false-unverified','docs/11-TEST-STRATEGY.md','| locally_verified | Backup tombstone','| unverified | Backup tombstone','gate',''),
 ('failed-local-proof','collectors/local/src/academic_os/backup.py','return {t:len(actual[t]) for t in ALLOWED}','return {t:0 for t in ALLOWED}','gate',''),
 ('missing-gate-test','docs/11-TEST-STRATEGY.md','test_restore_contract.CanonicalRestoreContractTests.test_all_eleven_tables_restore_counts_hashes_tombstones_without_dispatch_or_credentials','test_restore_contract.CanonicalRestoreContractTests.test_missing_assertion','gate',''),
]

def main():
 p=argparse.ArgumentParser();p.add_argument('--output-dir',type=Path,required=True);a=p.parse_args();out=a.output_dir.resolve()
 if out==ROOT or ROOT in out.parents:raise SystemExit('OUTPUT_MUST_BE_OUTSIDE_REPOSITORY')
 out.mkdir(parents=True,exist_ok=True)
 with tempfile.TemporaryDirectory(prefix='aos-round4-faults-') as tmp:
  fixture=Path(tmp)
  for folder in ['apps','packages','tests','schemas','collectors','examples','scripts','docs']:
   shutil.copytree(ROOT/folder,fixture/folder,ignore=shutil.ignore_patterns('node_modules','dist','build','.gradle','.wrangler','__pycache__','*-checks'))
  (fixture/'node_modules').symlink_to(ROOT/'node_modules',target_is_directory=True)
  for name in ['package.json','package-lock.json','vitest.config.ts','tsconfig.json']:shutil.copy2(ROOT/name,fixture/name)
  # Fault harness uses the same invariant at a cheap population. The required
  # full measurement, outside this fault harness, still runs 100/1200/10000.
  measure=fixture/'scripts/measure_resources.ts'
  measure.write_text(measure.read_text().replace('for (const size of [100, 1200, 10000])','for (const size of [100])'))
  # Measurement inventories real built artifacts; copy generated bytes only here.
  for rel in ['apps/web/dist','apps/worker/dist']:shutil.copytree(ROOT/rel,fixture/rel)
  def run(name,kind,pattern):
   if kind=='measure':command=['node','--import','tsx','scripts/measure_resources.ts',str(out/(name+'.json'))]
   elif kind=='gate':command=[str(ROOT/'.venv/bin/python'),'scripts/check_gate_claims.py']
   else:command=[str(ROOT/'.venv/bin/python'),'-m','unittest','discover','-s','collectors/local/tests','-p','test_'+kind+'.py','-k',pattern,'-v']
   r=subprocess.run(command,cwd=fixture,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,timeout=180,env={**os.environ,'AOS_TEST_PYTHON':sys.executable})
   (out/(name+'.txt')).write_text('COMMAND: '+' '.join(command)+'\n'+r.stdout+'\nEXIT: '+str(r.returncode)+'\n');return r
  for name,file,old,new,kind,pattern in CASES:
   path=fixture/file;original=path.read_text();assert original.count(old)==1,(name,original.count(old))
   assert run(name+'-baseline',kind,pattern).returncode==0,name+' baseline'
   try:
    path.write_text(original.replace(old,new,1));r=run(name+'-broken',kind,pattern)
    assert r.returncode!=0 and (('GATE_' in r.stdout) if kind=='gate' else 'AssertionError' in r.stdout) and not any(s in r.stdout for s in ['SyntaxError','Transform failed','FAILED (errors=']),name+' failed for wrong reason'
   finally:path.write_text(original)
   assert run(name+'-restored',kind,pattern).returncode==0,name+' restored'
   print(name+': intended failure; restored PASS',flush=True)
 print(f'PASS: {len(CASES)} intended failures; {len(CASES)} restored passes; 0 survivors; working sources untouched.')
if __name__=='__main__':main()
